#!/usr/bin/env bash
set -euo pipefail

repo_dir="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
version="$(tr -d '[:space:]' < "${repo_dir}/VERSION")"
tag="v${version}"
image="qurio:${tag}"
archive="qurio-${tag}.tar.gz"

if [[ ! "${version}" =~ ^[0-9]+\.[0-9]+\.[0-9]+([.-][0-9A-Za-z.-]+)?$ ]]; then
  echo "VERSION is not semantic: ${version}" >&2
  exit 1
fi

# Oracle connectivity must remain self-contained in the sealed image. These
# source checks complement verify-offline-image.sh, which loads the finished
# archive and confirms that no OCI/Instant Client files are present.
grep -Eq '^\s*github\.com/sijms/go-ora/v2 v[0-9]+' "${repo_dir}/go.mod"
grep -Fq 'CGO_ENABLED=0 GOOS=linux GOARCH=amd64 go build' "${repo_dir}/Dockerfile"
grep -Fq 'go_ora.BuildUrl(' "${repo_dir}/internal/domain/dbexec/manager.go"
grep -Fq 'Oracle uses a pure-Go driver' "${repo_dir}/internal/domain/dbexec/manager.go"

grep -Fqx 'IMAGE := qurio:v$(VERSION)' "${repo_dir}/Makefile"
grep -Fqx "    image: ${image}" "${repo_dir}/compose.yml"
node - "${repo_dir}/web/package.json" "${repo_dir}/web/package-lock.json" "${version}" <<'NODE'
const fs = require('node:fs');
const [packagePath, lockPath, expected] = process.argv.slice(2);
const packageJSON = JSON.parse(fs.readFileSync(packagePath, 'utf8'));
const lockJSON = JSON.parse(fs.readFileSync(lockPath, 'utf8'));
if (packageJSON.version !== expected || lockJSON.version !== expected || lockJSON.packages?.['']?.version !== expected) {
  throw new Error(`web version contract mismatch: expected ${expected}`);
}
NODE
grep -RFq "v${version}" "${repo_dir}/internal/webui/dist/assets"
# The release image must additionally rebuild that tracked UI from the checked
# package version and replace the embedded directory before linking Go.
grep -Fq 'const appVersion = `v${packageJson.version}`;' "${repo_dir}/web/vite.config.ts"
grep -Fq 'COPY --from=web-build /src/web/dist/ ./internal/webui/dist/' "${repo_dir}/Dockerfile"
grep -Fq "\"softwareVersion\": \"${version}\"" "${repo_dir}/docs/index.html"
grep -Fq "Complete product gallery · v${version}" "${repo_dir}/docs/gallery.html"
current_release_migration="$(find "${repo_dir}/migrations" -maxdepth 1 -type f -name '*release*.sql' | sort | tail -n 1)"
test -n "${current_release_migration}"
grep -Fq "'${version}','Qurio','${image}','${archive}'" "${current_release_migration}"
grep -Fq 'docker save "${image}" | gzip -n -9 > "${asset}"' "${repo_dir}/scripts/release.sh"
grep -Fq "docker save \"qurio:\${GITHUB_REF_NAME}\" | gzip -n -9 > \"qurio-\${GITHUB_REF_NAME}.tar.gz\"" "${repo_dir}/.github/workflows/release.yml"
grep -Fq '"${repo_dir}/scripts/verify-offline-image.sh" "${asset}" "${image}"' "${repo_dir}/scripts/release.sh"
grep -Fq './scripts/verify-offline-image.sh "qurio-${GITHUB_REF_NAME}.tar.gz" "qurio:${GITHUB_REF_NAME}"' "${repo_dir}/.github/workflows/release.yml"
test -x "${repo_dir}/scripts/verify-offline-image.sh"
release_create_block="$(awk '/gh release create/{capture=1} capture{print} /--title/{exit}' "${repo_dir}/.github/workflows/release.yml")"
[[ "$(printf '%s\n' "${release_create_block}" | grep -Ec '^[[:space:]]+"[^"]+"$')" == "1" ]]
printf '%s\n' "${release_create_block}" | grep -Fqx '          "qurio-${GITHUB_REF_NAME}.tar.gz"'
! grep -Eq 'gh[[:space:]]+release[[:space:]]+upload' "${repo_dir}/.github/workflows/release.yml"

for required in POSTGRES_DSN BOOTSTRAP_ADMIN BOOTSTRAP_ADMIN_PASSWORD ENCRYPTION_KEY; do
  grep -Eq "^[[:space:]]+${required}:" "${repo_dir}/compose.yml"
  grep -Eq "^${required}=" "${repo_dir}/.env.example"
done

compose_count="$(awk '/^[[:space:]]{6}[A-Z][A-Z0-9_]*: / { count += 1 } END { print count + 0 }' "${repo_dir}/compose.yml")"
