const fs = require('node:fs');
const path = require('node:path');
const manifest = JSON.parse(fs.readFileSync(process.argv[2], 'utf8'));
const gallery = fs.readFileSync(process.argv[5], 'utf8');
const screenshotRoot = path.dirname(process.argv[2]);
const documentationAssetRoot = path.dirname(screenshotRoot);
const requireScreenshot = (file, route) => {
  if (typeof file !== 'string' || file.length === 0 || path.basename(file) !== file) {
    throw new Error(`invalid screenshot filename for ${route}: ${file}`);
  }
  const target = path.join(screenshotRoot, file);
  let stat;
  try {
    stat = fs.statSync(target);
  } catch {
    throw new Error(`screenshot file is missing for ${route}: ${file}`);
  }
  if (!stat.isFile() || stat.size === 0) {
    throw new Error(`screenshot file is empty or invalid for ${route}: ${file}`);
  }
};
const routes = new Set();
for (const entry of manifest.entries ?? []) {
  if (!entry.route || routes.has(entry.route)) throw new Error(`invalid or duplicate screenshot route: ${entry.route}`);
  routes.add(entry.route);
  if (entry.required && !entry.file) throw new Error(`required screenshot is missing a file: ${entry.route}`);
  if (entry.required && !entry.title) throw new Error(`required screenshot is missing a title: ${entry.route}`);
  if (entry.mobile && !entry.mobile_file) throw new Error(`mobile screenshot is missing a mobile_file: ${entry.route}`);
  if (entry.required) requireScreenshot(entry.file, entry.route);
  if (entry.mobile) requireScreenshot(entry.mobile_file, `${entry.route} (mobile)`);
  if (entry.required && (!gallery.includes(`assets/screenshots/${entry.file}`) || !gallery.includes(`>${entry.route}</code>`))) {
    throw new Error(`required screenshot is not used by the gallery: ${entry.route}`);
  }
}
for (const asset of manifest.publication_assets ?? []) {
  if (!asset.required_before_public_release) continue;
  if (asset.status !== 'generated' || typeof asset.file !== 'string' || asset.file.length === 0) {
    throw new Error(`required publication asset is not generated: ${asset.file}`);
  }
  const target = path.resolve(screenshotRoot, asset.file);
  if (!target.startsWith(`${documentationAssetRoot}${path.sep}`)) {
    throw new Error(`publication asset escapes the documentation asset directory: ${asset.file}`);
  }
  let stat;
  try {
    stat = fs.statSync(target);
  } catch {
    throw new Error(`required publication asset is missing: ${asset.file}`);
  }
  if (!stat.isFile() || stat.size === 0) {
    throw new Error(`required publication asset is empty or invalid: ${asset.file}`);
  }
}

// Keep the documentation inventory mechanically exhaustive as routes evolve.
// Redirect aliases remain in the manifest as non-required entries; every stable
// screen is required and captured by the browser route/reload test.
const appSource = fs.readFileSync(process.argv[3], 'utf8');
const adminSource = fs.readFileSync(process.argv[4], 'utf8');
const literalRoutes = (source) => [...source.matchAll(/<Route\b[^>]*\bpath="([^"]+)"/g)].map((match) => match[1]);
const applicationRoutes = new Set(
  literalRoutes(appSource).filter((route) => route !== '*' && route !== '/admin/*'),
);
applicationRoutes.add('/admin');
for (const route of literalRoutes(adminSource)) {
  if (route !== '*') applicationRoutes.add(`/admin/${route}`);
}
const missingRoutes = [...applicationRoutes].filter((route) => !routes.has(route));
const staleRoutes = [...routes].filter((route) => !applicationRoutes.has(route));
if (missingRoutes.length || staleRoutes.length) {
  throw new Error(`screenshot route parity mismatch; missing=${missingRoutes.join(',')}; stale=${staleRoutes.join(',')}`);
}
NODE
